//! `ConnRef::has_valid_route()` and `has_crossing_obstacles()`, which the port
//! takes from the Adaptagrams fork that libavoid-js builds on
//! (Aksem/adaptagrams), against the C++ (golden:
//! `tests/fork_route_status/golden.txt`, regenerated by
//! `tools/oracle/fork_route_status.sh`).
//!
//! The C++ is the vendored upstream with the fork's two commits applied
//! (`tools/oracle/fork_route_status.patch`), which add the methods without
//! changing any route.  After every transaction of every scene, each live
//! connector's two flags and the size of its route must match (compared as
//! a hash per transaction, see `scene_replay::transaction_hashes`).

mod scene_replay;

use libavoid_rust::avoid::geomtypes::PolygonInterface;
use scene_replay::{golden_scenes, hashed_difference, replay};

const GOLDEN: &str = include_str!("fork_route_status/golden.txt");

#[test]
fn fork_route_status_matches_cpp() {
    let scenes = golden_scenes(GOLDEN);
    assert!(scenes.len() >= 100, "golden has only {} scenes", scenes.len());
    // Debug builds replay every 10th scene.
    let step = if cfg!(debug_assertions) { 10 } else { 1 };
    let (mut checked, mut invalid, mut crossing) = (0, 0, 0);
    let mut failures = Vec::new();
    for s in scenes.iter().step_by(step) {
        let mut ours = Vec::new();
        let mut t = 0;
        replay(
            &s.scene,
            |_| {},
            |r, conns| {
                ours.push(format!("T {t}"));
                t += 1;
                for (id, &c) in conns {
                    ours.push(format!(
                        "c {} {} {} {}",
                        id,
                        c.has_valid_route(r) as i32,
                        c.has_crossing_obstacles(r) as i32,
                        c.route(r).size()
                    ));
                }
            },
        );
        checked += 1;
        match hashed_difference(&ours, &s.expected[0].1) {
            Some(d) => failures.push(format!("{}: {d}", s.name)),
            None => {
                // Matching the C++: count what the golden exercises.
                invalid += ours.iter().filter(|l| l.split(' ').nth(2) == Some("0")).count();
                crossing += ours.iter().filter(|l| l.split(' ').nth(3) == Some("1")).count();
            }
        }
    }
    assert!(failures.is_empty(), "{} of {checked} scenes differ:\n{}", failures.len(), failures.join("\n"));
    // The golden must exercise both values of both flags.
    assert!(invalid > 0 && crossing > 0, "golden lacks invalid routes ({invalid}) or crossings ({crossing})");
}
